window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3c903b47dc217286"]={"versions": [{"id": "FIG-3c903b47dc217286", "releases": ["R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>class HM_DeadlineSupervision</code>) aus der Spezifikation des AUTOSAR Health Monitoring (HM) zur Modellierung der Laufzeitüberwachung via Deadline Supervision. Das Diagramm definiert die statischen Entitäten und Relationen zur Zeitüberwachung zwischen definierten Kontrollpunkten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst zwei Klassen:</p>\n<ul class=\"fig-list\">\n<li><code>DeadlineSupervision</code>: Besitzt die privaten Attribute <code>- MaxDeadline</code> und <code>- MinDeadline</code>.</li>\n<li><code>Checkpoint</code>: Repräsentiert einen Kontrollpunkt im überwachten Ablauf.</li>\n</ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Eine gerichtete Assoziation <code>DeadlineStart</code> von <code>DeadlineSupervision</code> zu <code>Checkpoint</code> mit Zielkardinalität <code>1</code>.</li>\n<li>Eine gerichtete Assoziation <code>DeadlineEnd</code> von <code>DeadlineSupervision</code> zu <code>Checkpoint</code> mit Zielkardinalität <code>1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Klassenstruktur dar. Die funktionale Semantik impliziert, dass beim Erreichen des durch <code>DeadlineStart</code> referenzierten Kontrollpunkts eine Zeitmessung gestartet und beim Erreichen des durch <code>DeadlineEnd</code> referenzierten Zielkontrollpunkts beendet wird. Das Health Monitoring prüft anschließend, ob das gemessene Zeitintervall zwischen <code>MinDeadline</code> und <code>MaxDeadline</code> liegt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurations- und Entwurfsmodell für die Deadline-Überwachung. Beide Kontrollpunkte müssen exakt einem Checkpoint zugeordnet sein (Kardinalität jeweils genau 1). Entwickler und Konfiguratoren müssen sicherstellen, dass <code>MinDeadline</code> und <code>MaxDeadline</code> konsistente Grenzwerte für den durch Start- und End-Checkpoint definierten Pfad vorgeben.</p>"}, {"id": "FIG-3f7765686cf61e27", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>class HM_DeadlineSupervision</code>) aus der Spezifikation des AUTOSAR Health Monitoring (HM) zur Modellierung der Laufzeitüberwachung via Deadline Supervision. Das Diagramm definiert die statischen Entitäten und Relationen zur Zeitüberwachung zwischen definierten Kontrollpunkten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst drei Klassen:</p>\n<ul class=\"fig-list\">\n<li><code>DeadlineSupervision</code>: Besitzt die privaten Attribute <code>- MaxDeadline</code> und <code>- MinDeadline</code>.</li>\n<li><code>CheckpointTransition</code>: Kapselt den Übergang zwischen zwei Kontrollpunkten.</li>\n<li><code>Checkpoint</code>: Repräsentiert einen Kontrollpunkt im überwachten Ablauf.</li>\n</ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Eine unbenannte gerichtete Assoziation von <code>DeadlineSupervision</code> zu <code>CheckpointTransition</code> mit Zielkardinalität <code>1</code>.</li>\n<li>Eine gerichtete Assoziation <code>Source</code> von <code>CheckpointTransition</code> zu <code>Checkpoint</code> mit Zielkardinalität <code>1</code>.</li>\n<li>Eine gerichtete Assoziation <code>Target</code> von <code>CheckpointTransition</code> zu <code>Checkpoint</code> mit Zielkardinalität <code>1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Klassenstruktur dar. Die funktionale Semantik impliziert, dass die Überwachung an einen durch <code>CheckpointTransition</code> modellierten Übergang gekoppelt ist: Beim Erreichen des über die Rolle <code>Source</code> angebundenen Checkpoints startet das Zeitfenster, beim Erreichen des über <code>Target</code> angebundenen Checkpoints stoppt es. Das Health Monitoring validiert die verstrichene Zeit gegen <code>MinDeadline</code> und <code>MaxDeadline</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurations- und Entwurfsmodell für die Deadline-Überwachung. Durch die Zwischenschaltung von <code>CheckpointTransition</code> wird der Transitionspfad von der Überwachungsdefinition entkoppelt. Eine <code>DeadlineSupervision</code> referenziert exakt eine <code>CheckpointTransition</code> (Kardinalität 1), welche wiederum genau einen Quell-Checkpoint (<code>Source: 1</code>) und genau einen Ziel-Checkpoint (<code>Target: 1</code>) referenziert. Die Konfiguration erfordert gültige Grenzwerte für <code>MinDeadline</code> und <code>MaxDeadline</code> auf der jeweiligen Transition.</p>"}], "trans": [{"from": "FIG-3c903b47dc217286", "to": "FIG-3f7765686cf61e27", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Einführung der Klasse <code>CheckpointTransition</code> zwischen <code>DeadlineSupervision</code> und <code>Checkpoint</code>.</li>\n<li>Ersatz der direkten Assoziationen <code>DeadlineStart</code> und <code>DeadlineEnd</code> (von <code>DeadlineSupervision</code> nach <code>Checkpoint</code>) durch eine gerichtete 1-zu-1-Assoziation von <code>DeadlineSupervision</code> zu <code>CheckpointTransition</code>.</li>\n<li>Einführung zweier gerichteter 1-zu-1-Assoziationen <code>Source</code> und <code>Target</code> von <code>CheckpointTransition</code> zu <code>Checkpoint</code>.</li>\n</ul>"}]};
